window.__code__["permission-types-py-18"] = {"code_id": "permission-types-py-18", "kind": "src", "title": "_types.py:18", "source_path": "agentscope/src/agentscope/permission/_types.py", "highlight_line": 18, "code_html": "<div class=\"code-body\">\n<div class=\"c-line\" data-line=\"1\"><span class=\"c-no\">1</span><span class=\"c-src\"><span class=\"c-com\"># -*- coding: utf-8 -*-</span></span></div>\n<div class=\"c-line\" data-line=\"2\"><span class=\"c-no\">2</span><span class=\"c-src\"><span class=\"c-com\"># pylint: disable=line-too-long</span></span></div>\n<div class=\"c-line\" data-line=\"3\"><span class=\"c-no\">3</span><span class=\"c-src\"><span class=\"c-str\">&quot;&quot;</span>&quot;Permission system types <span class=\"c-kw\">and</span> engine <span class=\"c-kw\">for</span> tool usage control.</span></div>\n<div class=\"c-line\" data-line=\"4\"><span class=\"c-no\">4</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"5\"><span class=\"c-no\">5</span><span class=\"c-src\">This module implements a permission system that controls tool execution based</span></div>\n<div class=\"c-line\" data-line=\"6\"><span class=\"c-no\">6</span><span class=\"c-src\">on configurable rules. The permission system supports different matching</span></div>\n<div class=\"c-line\" data-line=\"7\"><span class=\"c-no\">7</span><span class=\"c-src\">strategies depending on the tool type:</span></div>\n<div class=\"c-line\" data-line=\"8\"><span class=\"c-no\">8</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"9\"><span class=\"c-no\">9</span><span class=\"c-src\">- For Bash tools: rule_content <span class=\"c-kw\">is</span> a substring pattern matched against commands</span></div>\n<div class=\"c-line\" data-line=\"10\"><span class=\"c-no\">10</span><span class=\"c-src\">- For Write/Read tools: rule_content <span class=\"c-kw\">is</span> a glob pattern matched against file</span></div>\n<div class=\"c-line\" data-line=\"11\"><span class=\"c-no\">11</span><span class=\"c-src\"> paths</span></div>\n<div class=\"c-line\" data-line=\"12\"><span class=\"c-no\">12</span><span class=\"c-src\">- For other tools: rule_content uses generic matching logic</span></div>\n<div class=\"c-line\" data-line=\"13\"><span class=\"c-no\">13</span><span class=\"c-src\"><span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"14\"><span class=\"c-no\">14</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"15\"><span class=\"c-no\">15</span><span class=\"c-src\"><span class=\"c-kw\">from</span> enum <span class=\"c-kw\">import</span> Enum</span></div>\n<div class=\"c-line\" data-line=\"16\"><span class=\"c-no\">16</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"17\"><span class=\"c-no\">17</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"18\"><span class=\"c-no\">18</span><span class=\"c-src\"><span class=\"c-kw\">class</span> PermissionMode(Enum):</span></div>\n<div class=\"c-line\" data-line=\"19\"><span class=\"c-no\">19</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;The mode of permission.</span></div>\n<div class=\"c-line\" data-line=\"20\"><span class=\"c-no\">20</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"21\"><span class=\"c-no\">21</span><span class=\"c-src\">    Permission modes control how the system handles tool execution requests.</span></div>\n<div class=\"c-line\" data-line=\"22\"><span class=\"c-no\">22</span><span class=\"c-src\">    Different modes are suitable <span class=\"c-kw\">for</span> different scenarios:</span></div>\n<div class=\"c-line\" data-line=\"23\"><span class=\"c-no\">23</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"24\"><span class=\"c-no\">24</span><span class=\"c-src\">    +---------------+--------------------------------------------------+--------------------------------+</span></div>\n<div class=\"c-line\" data-line=\"25\"><span class=\"c-no\">25</span><span class=\"c-src\">    | Mode          | Behavior                                         | Use Case                       |</span></div>\n<div class=\"c-line\" data-line=\"26\"><span class=\"c-no\">26</span><span class=\"c-src\">    +===============+==================================================+================================+</span></div>\n<div class=\"c-line\" data-line=\"27\"><span class=\"c-no\">27</span><span class=\"c-src\">    | DEFAULT       | Every operation asks <span class=\"c-kw\">for</span> permission unless:      | Default mode, most secure      |</span></div>\n<div class=\"c-line\" data-line=\"28\"><span class=\"c-no\">28</span><span class=\"c-src\">    |               | - an allow rule matches, OR                      |                                |</span></div>\n<div class=\"c-line\" data-line=\"29\"><span class=\"c-no\">29</span><span class=\"c-src\">    |               | - the tool&<span class=\"c-com\">#x27;s ``check_permissions`` explicitly    |                                |</span></span></div>\n<div class=\"c-line\" data-line=\"30\"><span class=\"c-no\">30</span><span class=\"c-src\">    |               |   returns ALLOW <span class=\"c-kw\">for</span> the invocation (currently   |                                |</span></div>\n<div class=\"c-line\" data-line=\"31\"><span class=\"c-no\">31</span><span class=\"c-src\">    |               |   only ``Bash`` auto-allows recognized          |                                |</span></div>\n<div class=\"c-line\" data-line=\"32\"><span class=\"c-no\">32</span><span class=\"c-src\">    |               |   read-only commands such <span class=\"c-kw\">as</span> ``ls``/``git       |                                |</span></div>\n<div class=\"c-line\" data-line=\"33\"><span class=\"c-no\">33</span><span class=\"c-src\">    |               |   status``). Read/Glob/Grep <span class=\"c-kw\">return</span> PASSTHROUGH  |                                |</span></div>\n<div class=\"c-line\" data-line=\"34\"><span class=\"c-no\">34</span><span class=\"c-src\">    |               |   <span class=\"c-kw\">and</span> fall through to the default ASK unless    |                                |</span></div>\n<div class=\"c-line\" data-line=\"35\"><span class=\"c-no\">35</span><span class=\"c-src\">    |               |   an allow rule matches.                        |                                |</span></div>\n<div class=\"c-line\" data-line=\"36\"><span class=\"c-no\">36</span><span class=\"c-src\">    +---------------+--------------------------------------------------+--------------------------------+</span></div>\n<div class=\"c-line\" data-line=\"37\"><span class=\"c-no\">37</span><span class=\"c-src\">    | ACCEPT_EDITS  | - Auto-allow file writes <span class=\"c-kw\">in</span> working directories | User present, rapid iteration  |</span></div>\n<div class=\"c-line\" data-line=\"38\"><span class=\"c-no\">38</span><span class=\"c-src\">    |               | - Auto-allow file reads <span class=\"c-kw\">in</span> working directories  | development                    |</span></div>\n<div class=\"c-line\" data-line=\"39\"><span class=\"c-no\">39</span><span class=\"c-src\">    |               | - Auto-allow filesystem commands (mkdir, rm,     |                                |</span></div>\n<div class=\"c-line\" data-line=\"40\"><span class=\"c-no\">40</span><span class=\"c-src\">    |               |   mv, cp, ...) **only when all target paths**   |                                |</span></div>\n<div class=\"c-line\" data-line=\"41\"><span class=\"c-no\">41</span><span class=\"c-src\">    |               |   **resolve inside a working directory**         |                                |</span></div>\n<div class=\"c-line\" data-line=\"42\"><span class=\"c-no\">42</span><span class=\"c-src\">    |               | - Other operations follow normal rules           |                                |</span></div>\n<div class=\"c-line\" data-line=\"43\"><span class=\"c-no\">43</span><span class=\"c-src\">    +---------------+--------------------------------------------------+--------------------------------+</span></div>\n<div class=\"c-line\" data-line=\"44\"><span class=\"c-no\">44</span><span class=\"c-src\">    | EXPLORE       | Read-only mode:                                  | Exploring codebase, planning   |</span></div>\n<div class=\"c-line\" data-line=\"45\"><span class=\"c-no\">45</span><span class=\"c-src\">    |               | - Allow: read-only tools (``Read``/``Grep``/    | implementation                 |</span></div>\n<div class=\"c-line\" data-line=\"46\"><span class=\"c-no\">46</span><span class=\"c-src\">    |               |   ``Glob``) <span class=\"c-kw\">and</span> read-only bash commands         |                                |</span></div>\n<div class=\"c-line\" data-line=\"47\"><span class=\"c-no\">47</span><span class=\"c-src\">    |               |   (e.g. ``ls``, ``git status``)                  |                                |</span></div>\n<div class=\"c-line\" data-line=\"48\"><span class=\"c-no\">48</span><span class=\"c-src\">    |               | - Deny: any modification tool / command         |                                |</span></div>\n<div class=\"c-line\" data-line=\"49\"><span class=\"c-no\">49</span><span class=\"c-src\">    |               | - User-configured DENY <span class=\"c-kw\">or</span> ASK rules take         |                                |</span></div>\n<div class=\"c-line\" data-line=\"50\"><span class=\"c-no\">50</span><span class=\"c-src\">    |               |   precedence over the read-only auto-allow      |                                |</span></div>\n<div class=\"c-line\" data-line=\"51\"><span class=\"c-no\">51</span><span class=\"c-src\">    +---------------+--------------------------------------------------+--------------------------------+</span></div>\n<div class=\"c-line\" data-line=\"52\"><span class=\"c-no\">52</span><span class=\"c-src\">    | BYPASS        | Skip all permission checks <span class=\"c-kw\">except</span> explicit       | Sandboxed environments         |</span></div>\n<div class=\"c-line\" data-line=\"53\"><span class=\"c-no\">53</span><span class=\"c-src\">    |               | user-configured deny / ask rules <span class=\"c-kw\">and</span> tool       | (container, VM), unattended    |</span></div>\n<div class=\"c-line\" data-line=\"54\"><span class=\"c-no\">54</span><span class=\"c-src\">    |               | DENY. **Safety ASKs <span class=\"c-kw\">from</span> tools are NOT**         | runs where you fully trust     |</span></div>\n<div class=\"c-line\" data-line=\"55\"><span class=\"c-no\">55</span><span class=\"c-src\">    |               | **enforced** — including ``rm -rf /``, writes   | the agent                      |</span></div>\n<div class=\"c-line\" data-line=\"56\"><span class=\"c-no\">56</span><span class=\"c-src\">    |               | to ``~/.bashrc``, command-injection patterns,    |                                |</span></div>\n<div class=\"c-line\" data-line=\"57\"><span class=\"c-no\">57</span><span class=\"c-src\">    |               | etc. Use deny rules to protect specific paths.   |                                |</span></div>\n<div class=\"c-line\" data-line=\"58\"><span class=\"c-no\">58</span><span class=\"c-src\">    |               | For unattended runs that still need safety,      |                                |</span></div>\n<div class=\"c-line\" data-line=\"59\"><span class=\"c-no\">59</span><span class=\"c-src\">    |               | prefer DONT_ASK.                                 |                                |</span></div>\n<div class=\"c-line\" data-line=\"60\"><span class=\"c-no\">60</span><span class=\"c-src\">    +---------------+--------------------------------------------------+--------------------------------+</span></div>\n<div class=\"c-line\" data-line=\"61\"><span class=\"c-no\">61</span><span class=\"c-src\">    | DONT_ASK      | Convert every ASK (including safety ASKs <span class=\"c-kw\">and</span>     | Scheduled tasks, background    |</span></div>\n<div class=\"c-line\" data-line=\"62\"><span class=\"c-no\">62</span><span class=\"c-src\">    |               | ASK-rule hits) to DENY. Safe-by-default <span class=\"c-kw\">for</span>     | execution when user <span class=\"c-kw\">is</span> away    |</span></div>\n<div class=\"c-line\" data-line=\"63\"><span class=\"c-no\">63</span><span class=\"c-src\">    |               | unattended execution.                            |                                |</span></div>\n<div class=\"c-line\" data-line=\"64\"><span class=\"c-no\">64</span><span class=\"c-src\">    +---------------+--------------------------------------------------+--------------------------------+</span></div>\n<div class=\"c-line\" data-line=\"65\"><span class=\"c-no\">65</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"66\"><span class=\"c-no\">66</span><span class=\"c-src\">    Attributes:</span></div>\n<div class=\"c-line\" data-line=\"67\"><span class=\"c-no\">67</span><span class=\"c-src\">        DEFAULT: Default mode - explicit permission per action. The</span></div>\n<div class=\"c-line\" data-line=\"68\"><span class=\"c-no\">68</span><span class=\"c-src\">            only auto-allow path <span class=\"c-kw\">is</span> the tool&<span class=\"c-com\">#x27;s own ``check_permissions``</span></span></div>\n<div class=\"c-line\" data-line=\"69\"><span class=\"c-no\">69</span><span class=\"c-src\">            returning ALLOW (currently just ``Bash`` <span class=\"c-kw\">for</span> recognized</span></div>\n<div class=\"c-line\" data-line=\"70\"><span class=\"c-no\">70</span><span class=\"c-src\">            read-only commands like ``ls``/``git status``).</span></div>\n<div class=\"c-line\" data-line=\"71\"><span class=\"c-no\">71</span><span class=\"c-src\">        ACCEPT_EDITS: Accept edits mode - automatically allows file</span></div>\n<div class=\"c-line\" data-line=\"72\"><span class=\"c-no\">72</span><span class=\"c-src\">            edits within working directories (including filesystem</span></div>\n<div class=\"c-line\" data-line=\"73\"><span class=\"c-no\">73</span><span class=\"c-src\">            bash commands whose every target <span class=\"c-kw\">is</span> <span class=\"c-kw\">in</span> a working dir).</span></div>\n<div class=\"c-line\" data-line=\"74\"><span class=\"c-no\">74</span><span class=\"c-src\">        EXPLORE: Explore mode - read-only; modifications are denied.</span></div>\n<div class=\"c-line\" data-line=\"75\"><span class=\"c-no\">75</span><span class=\"c-src\">        BYPASS: Bypass mode - skips safety checks; relies on user</span></div>\n<div class=\"c-line\" data-line=\"76\"><span class=\"c-no\">76</span><span class=\"c-src\">            deny / ask rules <span class=\"c-kw\">as</span> the only guardrail.</span></div>\n<div class=\"c-line\" data-line=\"77\"><span class=\"c-no\">77</span><span class=\"c-src\">        DONT_ASK: Don&<span class=\"c-com\">#x27;t ask mode - converts all ASK decisions to DENY</span></span></div>\n<div class=\"c-line\" data-line=\"78\"><span class=\"c-no\">78</span><span class=\"c-src\">            (<span class=\"c-kw\">for</span> unattended execution).</span></div>\n<div class=\"c-line\" data-line=\"79\"><span class=\"c-no\">79</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;  <span class=\"c-com\"># noqa: E501</span></span></div>\n<div class=\"c-line\" data-line=\"80\"><span class=\"c-no\">80</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"81\"><span class=\"c-no\">81</span><span class=\"c-src\">    DEFAULT = <span class=\"c-str\">&quot;default&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"82\"><span class=\"c-no\">82</span><span class=\"c-src\">    ACCEPT_EDITS = <span class=\"c-str\">&quot;accept_edits&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"83\"><span class=\"c-no\">83</span><span class=\"c-src\">    EXPLORE = <span class=\"c-str\">&quot;explore&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"84\"><span class=\"c-no\">84</span><span class=\"c-src\">    BYPASS = <span class=\"c-str\">&quot;bypass&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"85\"><span class=\"c-no\">85</span><span class=\"c-src\">    DONT_ASK = <span class=\"c-str\">&quot;dont_ask&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"86\"><span class=\"c-no\">86</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"87\"><span class=\"c-no\">87</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"88\"><span class=\"c-no\">88</span><span class=\"c-src\"><span class=\"c-kw\">class</span> PermissionBehavior(Enum):</span></div>\n<div class=\"c-line\" data-line=\"89\"><span class=\"c-no\">89</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;The behavior of permission.</span></div>\n<div class=\"c-line\" data-line=\"90\"><span class=\"c-no\">90</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"91\"><span class=\"c-no\">91</span><span class=\"c-src\">    Attributes:</span></div>\n<div class=\"c-line\" data-line=\"92\"><span class=\"c-no\">92</span><span class=\"c-src\">        ALLOW: Allow the operation</span></div>\n<div class=\"c-line\" data-line=\"93\"><span class=\"c-no\">93</span><span class=\"c-src\">        DENY: Deny the operation</span></div>\n<div class=\"c-line\" data-line=\"94\"><span class=\"c-no\">94</span><span class=\"c-src\">        ASK: Ask the user <span class=\"c-kw\">for</span> permission</span></div>\n<div class=\"c-line\" data-line=\"95\"><span class=\"c-no\">95</span><span class=\"c-src\">        PASSTHROUGH: Let the permission engine <span class=\"c-kw\">continue</span> <span class=\"c-kw\">with</span> rule matching</span></div>\n<div class=\"c-line\" data-line=\"96\"><span class=\"c-no\">96</span><span class=\"c-src\">            (used by tools to defer decision to the engine)</span></div>\n<div class=\"c-line\" data-line=\"97\"><span class=\"c-no\">97</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"98\"><span class=\"c-no\">98</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"99\"><span class=\"c-no\">99</span><span class=\"c-src\">    ALLOW = <span class=\"c-str\">&quot;allow&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"100\"><span class=\"c-no\">100</span><span class=\"c-src\">    DENY = <span class=\"c-str\">&quot;deny&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"101\"><span class=\"c-no\">101</span><span class=\"c-src\">    ASK = <span class=\"c-str\">&quot;ask&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"102\"><span class=\"c-no\">102</span><span class=\"c-src\">    PASSTHROUGH = <span class=\"c-str\">&quot;passthrough&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"103\"><span class=\"c-no\">103</span><span class=\"c-src\">&nbsp;</span></div>\n</div>", "lines": 103, "explanation": "_types.py 来自 agentscope/QwenPaw 框架源码。结合左侧源码与右侧知识点理解此处设计意图；点「反向链接」可回到引用它的教程章节。", "knowledge_points": [], "related_docs": ["W06-工具体系与MCP"]};
